import XCTest

@testable import CodeConnect
@testable import CodeConnectKit

/// **Ending a run, against the daemon's own bytes** (minor 35).
///
/// `minor-35-wire.json` is what ccd emits (`fixtures/claude/`, regenerated by ccd's tests
/// and copied here byte for byte); `minor-28-wire.json` is what an older daemon emitted.
@MainActor
final class Minor35WireTests: XCTestCase {

    private let uid = "01K1B3XQ8ZC0DE5FGH7JKMNPQR"

    private func wire(_ minor: Int) throws -> [String: JSONValue] {
        let url = try XCTUnwrap(
            Bundle(for: type(of: self)).url(forResource: "minor-\(minor)-wire", withExtension: "json"))
        return try XCTUnwrap(
            try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
    }

    private func frame(_ key: String) throws -> ServerMessage {
        let value = try XCTUnwrap(try wire(35)[key], "no \(key) in minor-35-wire.json")
        return try JSONDecoder().decode(ServerMessage.self, from: Data(value.canonicalJSONString.utf8))
    }

    private func capabilities(_ minor: Int) throws -> Capabilities {
        let advertised = try XCTUnwrap(try wire(minor)["hello_ack_capabilities"])
        return try JSONDecoder().decode(Capabilities.self, from: Data(advertised.canonicalJSONString.utf8))
    }

    func testADaemonThatEndsRunsSaysSoAndAnOlderOneDoesNot() throws {
        XCTAssertTrue(try capabilities(35).endsRuns)
        XCTAssertFalse(try capabilities(28).endsRuns)
    }

    func testEachStopRunAnswerDecodesAsTheDaemonSentIt() throws {
        let answers: [(String, StopRunResult)] = [
            ("stop_run_stopping", .stopping),
            ("stop_run_already_ended", .alreadyEnded),
            ("stop_run_refused", .refused(reason: "There is no such session on this computer.")),
        ]
        for (key, expected) in answers {
            guard case .stopRunResult(let session, let request, let result) = try frame(key) else {
                XCTFail("\(key) is not a stop_run_result")
                continue
            }
            XCTAssertEqual(session, uid, key)
            XCTAssertEqual(request, "stop-1", key)
            XCTAssertEqual(result, expected, key)
        }
    }

    func testARunThatIsStoppingReadsAsStopping() throws {
        guard case .sessions(let list) = try frame("sessions") else {
            return XCTFail("sessions is not a sessions frame")
        }
        XCTAssertEqual(list.map(\.lifecycle), [.stopping])
    }

    func testTheStopRunRequestIsTheBytesTheDaemonReads() throws {
        let sent = try JSONDecoder().decode(
            JSONValue.self,
            from: JSONEncoder().encode(ClientMessage.stopRun(session: uid, requestID: "stop-1")))
        XCTAssertEqual(sent, try XCTUnwrap(try wire(35)["stop_run_request"]))
    }

    /// The gate is on the send, not on a button: with no `stop_run` advertised no frame
    /// leaves; with it, one does, and its answer comes back to the caller.
    func testAStopRunLeavesOnlyForADaemonThatAdvertisesIt() async throws {
        for advertised in [false, true] {
            let model = AppModel(
                cache: EventCache(),
                codexSpentLedger: CodexSpentLedger(
                    defaults: UserDefaults(suiteName: "cc.tests.\(UUID().uuidString)")!))
            model.connection.simulateConnectedForTesting()
            model.connection.simulateCapabilitiesForTesting(
                Capabilities(
                    canApproveReliably: true, sendText: true,
                    extra: ["stop_run": .bool(advertised)]),
                minor: advertised ? 35 : 34)
            var sent: [ClientMessage] = []
            model.connection.sendStub = { [weak connection = model.connection] message in
                sent.append(message)
                if case .stopRun(let session, let requestID) = message {
                    connection?.injectForTesting(
                        .stopRunResult(sessionID: session, requestID: requestID, result: .stopping))
                }
            }
            do {
                let result = try await model.connection.stopRun(session: uid, requestID: "stop-1")
                XCTAssertTrue(advertised, "a stop was sent to a daemon that cannot answer it")
                XCTAssertEqual(result, .stopping)
                XCTAssertEqual(sent.count, 1)
            } catch {
                XCTAssertFalse(advertised, "\(error)")
                XCTAssertTrue(sent.isEmpty, "a frame left without the capability")
            }
        }
    }
}
